-- Qualified original bIa visual scripts. No scenario/server callbacks are executed.
CREATE TABLE native_script_item_actions (
 item_ref integer PRIMARY KEY CHECK(item_ref>0),
 action_id integer NOT NULL UNIQUE CHECK(action_id>0),
 consumes_source boolean NOT NULL,
 source_sha256 text NOT NULL CHECK(source_sha256 ~ '^[0-9a-f]{64}$')
);
